const $ = selector => document.querySelector(selector);
const menu=$('#menuToggle'), mobile=$('#mobileNav');
menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'关闭导航':'打开导航');menu.textContent=open?'×':'☰';mobile.hidden=!open});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!mobile.hidden){mobile.hidden=true;menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','打开导航');menu.textContent='☰';menu.focus()}});
const intro=$('.intro');if(intro){$('#skip').onclick=()=>intro.classList.add('done');setTimeout(()=>intro.classList.add('done'),2900)}
if($('#products')){let filter='all';const cards=[...document.querySelectorAll('.product')];function applyFilter(){const term=$('#search').value.trim().toLowerCase();let count=0;for(const card of cards){const match=(filter==='all'||card.dataset.type===filter)&&card.textContent.toLowerCase().includes(term);card.hidden=!match;if(match)count++}$('#resultCount').textContent=count+' 个系列';$('#empty').hidden=count!==0}document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{filter=button.dataset.filter;document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button))});applyFilter()});$('#search').addEventListener('input',applyFilter)}
if($('#consultForm')){const params=new URLSearchParams(location.search);for(const [param,id] of [['work','interest'],['topic','topic']]){const input=$('#'+id);if([...input.options].some(o=>o.value===params.get(param)))input.value=params.get(param)}const selected=id=>{const s=$('#'+id);return s.options[s.selectedIndex].text};$('#consultForm').onsubmit=event=>{event.preventDefault();$('#consultText').textContent=['你好，我想咨询森晖的作品与服务。','',`咨询方向：${selected('topic')}`,`感兴趣的作品：${selected('interest')}`,`尺寸 / 数量：${$('#size').value.trim()||'待沟通'}`,`预算范围：${$('#budget').value.trim()||'待沟通'}`,`具体需求：${$('#message').value.trim()||'希望了解实物、材质、尺寸、价格与库存。'}`,'','也请告知适用的证书、交付与售后说明，谢谢。'].join('\n');$('#consultResult').hidden=false;$('#copyStatus').textContent='清单已生成，尚未发送。'};$('#copy').onclick=async()=>{try{await navigator.clipboard.writeText($('#consultText').textContent);$('#copyStatus').textContent='已复制，可粘贴给店铺。'}catch{$('#copyStatus').textContent='复制未完成，请选中上方清单手动复制。'}};const config=window.SENHUI_CONFIG||{};if(config.wechat||config.telephone||config.email){$('#contactChannel').textContent=config.wechat?'微信：'+config.wechat:config.telephone?'电话：'+config.telephone:config.email;$('#contactHint').textContent='可复制咨询清单，通过以下渠道与店铺沟通。';const box=$('#channelLinks');for(const [value,prefix,text] of [[config.telephone,'tel:','电话咨询'],[config.email,'mailto:','邮件咨询']])if(value){const a=document.createElement('a');a.href=prefix+value;a.className='text-link';a.textContent=text+' ↗';box.append(a)}if(config.qrImage&&/^assets\/[\w./-]+$/.test(config.qrImage)){const image=document.createElement('img');image.src=config.qrImage;image.alt='店铺微信二维码';image.width=180;box.append(image)}}}
